namespace {
int checks=0,failures=0;
void expect(bool value,const char* text){++checks;if(!value){++failures;std::cerr<<"FAIL: "<<text<<'\n';}}
template<class F>void rejects(F f,const char* text){bool rejected=false;try{f();}catch(const std::exception&){rejected=true;}expect(rejected,text);}
penta::language::OdeDefinition model(const std::string& source){const auto checked=penta::language::analyse(source);if(!checked.ok())throw std::runtime_error("Native network test model failed checking.");return *checked.program.statements.front().ode;}
void driver(const std::filesystem::path& temp){
    using namespace penta;const auto stationary=model("ode stationary(t,real x){x'=0*x;}");networks::Graph edge{2,false,{1,2},{1}};networks::Options options;options.t1=1;options.step=.01;options.sampleStep=.1;options.diffusion={.7};options.threads=1;ode::NativeOptions native;native.cacheDirectory=temp/"odes";std::size_t compilations=0;std::atomic_size_t work=0;native.compilationFinished=[&](double){++compilations;};native.chargeOperations=[&](std::size_t count){work.fetch_add(count);};networks::Module solver;
    const auto real=solver.solve(stationary,edge,1,{1,3},{},options,native);const auto count=real.times.size();expect(count==11&&real.values.size()==22,"Native network retains every requested time and stable node coefficient.");const auto decay=std::exp(-1.4);expect(std::abs(real.values[2*count-2]-(2-decay))<2e-10&&std::abs(real.values.back()-(2+decay))<2e-10,"Two-node diffusion matches an independent analytic exponential.");bool conserved=true;for(double value:real.means)conserved=conserved&&std::abs(value-2)<1e-14;expect(conserved,"Undirected real graph diffusion preserves the component mean.");expect(std::abs(real.synchronization.back()-decay)<2e-10,"Euclidean synchronization RMS matches exact two-node decay.");expect(real.parallel.threadsUsed==1&&work>0,"Serial network uses one shared CPU slot and charges native work.");
    options.threads=4;const auto parallel=solver.solve(stationary,edge,1,{1,3},{},options,native);expect(parallel.values==real.values&&parallel.means==real.means,"Parallel per-node evaluation preserves serial scientific output exactly.");expect(parallel.parallel.threadsUsed<=4,"Network worker count respects per-call CPU maximum.");expect(parallel.key==real.key&&parallel.cacheHit&&compilations==1,"Thread settings and reruns reuse the exact ODE structural binary.");
    edge.directed=true;edge.weights={2};options.diffusion={.5};const auto directed=solver.solve(stationary,edge,1,{1,3},{},options,native);expect(std::abs(directed.values[2*count-2]-1)<1e-15&&std::abs(directed.values.back()-(1+2*std::exp(-1.)))<1e-9,"Directed source-to-target influence keeps source fixed and moves only target.");
    const auto pentarnion=model("ode pentarnion_node(t,pentarnion p){p'=0*p;}");edge.directed=false;edge.weights={1};options.diffusion={0,.2,.4,.6,.8};const std::vector<double> initial{1,1,2,3,4,-1,2,-2,1,0};const auto p=solver.solve(pentarnion,edge,.25,initial,{},options,native);expect(p.stateWidths==std::vector<std::size_t>{5}&&p.values.size()==count*10,"Pentarnion nodes retain all five typed coordinates.");for(std::size_t c=0;c<5;++c){const double mean=(initial[c]+initial[5+c])*.5,difference=(initial[c]-initial[5+c])*.5*std::exp(-2*options.diffusion[c]);expect(std::abs(p.values[(count-1)*10+c]-mean-difference)<2e-9&&std::abs(p.means[(count-1)*5+c]-mean)<1e-14,"Each Pentarnion coefficient matches its independent real diffusion solution.");}
    const auto linear=model("ode linear_node(t,real x;real alpha){x'=-alpha*x;}");networks::Graph isolated{3,false,{},{}};options.diffusion={0};const auto first=solver.solve(linear,isolated,1,{1,2,3},{2},options,native);const auto compiled=compilations;isolated.nodes=4;const auto changed=solver.solve(linear,isolated,.5,{1,2,3,4},{3},options,native);expect(changed.key==first.key&&changed.cacheHit&&compilations==compiled,"Node count, topology, gamma and runtime parameters do not recompile a node body.");expect(std::abs(changed.values.back()-4*std::exp(-3.))<2e-8,"Changed runtime parameter reaches every native node callback.");
    const auto mixed=model("ode mixed(t,real x,pentarnion p){x'=-x;p'=i*p;}");ode::PreparedModel prepared(mixed,native);std::vector<double> state{2,1,1,2,3,4},rhs(6),jac(36);prepared.evaluateValues(.5,.1,state,{},rhs,native);const auto evaluated=prepared.evaluate(.5,.1,state,{},native);prepared.evaluateJacobian(.5,.1,state,{},rhs,jac,native);expect(rhs==evaluated.rhs&&jac==evaluated.jacobian,"Allocation-free spans use the identical generated value/Jacobian kernel.");networks::Graph one{1,false,{},{}};options.t1=.2;options.step=.001;options.sampleStep=.1;const auto mixedNetwork=solver.solve(mixed,one,.5,state,{},options,native);ode::SolveOptions reference;reference.t1=.2;reference.sampleStep=.1;reference.method=ode::Method::Adams;reference.rtol=1e-12;reference.atol=1e-13;const auto ordinary=prepared.solve(.5,state,{},reference,native);double error=0;for(std::size_t i=0;i<ordinary->values.size();++i)error=std::max(error,std::abs(ordinary->values[i]-mixedNetwork.values[i]));expect(error<3e-10&&mixedNetwork.key==ordinary->stats.key&&mixedNetwork.stateWidths==std::vector<std::size_t>{1,5},"Mixed real/Pentarnion node agrees with ordinary native ODE and shares its exact cache key.");
    const auto growth=model("ode growth(t,real x){x'=x;}");options.t1=1;options.sampleStep=1;options.step=.2;const auto coarse=solver.solve(growth,one,1,{1},{},options,native);options.step=.1;const auto fine=solver.solve(growth,one,1,{1},{},options,native);expect(std::abs(fine.values.back()-std::exp(1.))<std::abs(coarse.values.back()-std::exp(1.))/12,"RK4 refinement demonstrates fourth-order global convergence.");
    const auto stiff=model("ode stiff_node(t,real x){x'=-1000*x;}");networks::Options bdf;bdf.method=2;bdf.step=0;bdf.t1=.01;bdf.sampleStep=.001;bdf.rtol=1e-10;bdf.atol=1e-12;bdf.diffusion={500};bdf.threads=4;edge.directed=false;edge.weights={1};const auto stiffResult=solver.solve(stiff,edge,1,{1,3},{},bdf,native);double stiffError=0;for(std::size_t row=0;row<stiffResult.times.size();++row){const double t=stiffResult.times[row],mean=2*std::exp(-1000*t),delta=std::exp(-2000*t);stiffError=std::max({stiffError,std::abs(stiffResult.values[2*row]-mean+delta),std::abs(stiffResult.values[2*row+1]-mean-delta)});}expect(stiffError<2e-8,"Matrix-free BDF matches a two-scale independent stiff exponential reference.");expect(stiffResult.report.local_jacobian_evaluations>0&&stiffResult.report.jacobian_vector_products>0&&stiffResult.report.block_factorizations>0&&stiffResult.report.linear_iterations>0,"BDF reports actual generated Jacobian, SPGMR and block-Jacobi work.");
    bdf.t1=1;bdf.sampleStep=.1;bdf.diffusion={.7};const auto conservative=solver.solve(pentarnion,edge,.25,initial,{},bdf,native);bool allMeans=true;for(std::size_t row=0;row<conservative.times.size();++row)for(std::size_t c=0;c<5;++c)allMeans=allMeans&&std::abs(conservative.means[row*5+c]-(initial[c]+initial[5+c])*.5)<2e-12;expect(allMeans&&conservative.stateWidths==std::vector<std::size_t>{5},"BDF graph diffusion preserves all five Pentarnion coordinate means.");bdf.t1=.2;bdf.sampleStep=.1;bdf.diffusion={0};const auto mixedBdf=solver.solve(mixed,one,.5,state,{},bdf,native);double mixedError=0;for(std::size_t i=0;i<ordinary->values.size();++i)mixedError=std::max(mixedError,std::abs(ordinary->values[i]-mixedBdf.values[i]));expect(mixedError<2e-9&&mixedBdf.key==mixedNetwork.key,"Generated full local blocks support mixed real/Pentarnion BDF states without recompilation.");
    networks::Graph large;large.nodes=4096;for(uint64_t node=1;node<large.nodes;++node){large.endpoints.push_back(node);large.endpoints.push_back(node+1);large.weights.push_back(1);}auto sparseBdf=bdf;sparseBdf.t1=.001;sparseBdf.sampleStep=.001;sparseBdf.diffusion={1000};sparseBdf.maximumBytes=8*1024*1024;const auto largeNetwork=solver.solve(stationary,large,1,std::vector<double>(large.nodes,1),{},sparseBdf,native);expect(largeNetwork.report.steps>0&&std::all_of(largeNetwork.values.begin(),largeNetwork.values.end(),[](double value){return value==1;}),"4096-node BDF field fits8 MiB estimate without a134 MiB global dense matrix.");
    struct Outer {const language::OdeDefinition& model;const networks::Graph& graph;const ode::NativeOptions& native;networks::Options options;std::array<std::size_t,2> slots{};static int run(void* raw,uint64_t first,uint64_t last,char* error,uint64_t capacity)noexcept{auto& o=*static_cast<Outer*>(raw);try{for(auto row=first;row<last;++row){const auto result=networks::Module().solve(o.model,o.graph,1,{1,3},{},o.options,o.native);o.slots[row]=result.parallel.threadsUsed;}return 0;}catch(const std::exception& e){if(error&&capacity){const auto text=std::string(e.what()).substr(0,capacity-1);std::copy(text.begin(),text.end(),error);error[text.size()]=0;}return 1;}}};edge.weights={1};networks::Options inner;inner.t1=.01;inner.sampleStep=.01;inner.step=.001;inner.threads=4;Outer outer{stationary,edge,native,inner,{}};runtime::ParallelSettings outerSettings;outerSettings.threads=2;outerSettings.serialThreshold=1;runtime::ParallelStatistics observed;std::string outerError;const int outerStatus=runtime::ThreadBudget::instance().run(2,100,Outer::run,&outer,outerSettings,{},observed,outerError);expect(outerStatus==0&&outer.slots[0]==1&&outer.slots[1]==1,"Outer native experiments force inner network workers to one shared CPU slot.");
    auto limited=options;limited.maximumBytes=1024;limited.maximumCoordinates=1;rejects([&]{solver.solve(growth,one,1,{1},{},limited,native);},"Retained data budget rejects before integration.");limited=options;limited.maximumSeconds=1e-9;rejects([&]{solver.solve(growth,one,1,{1},{},limited,native);},"Native network wall-time budget is explicit and enforced.");limited=options;limited.maximumWork=1;rejects([&]{solver.solve(growth,one,1,{1},{},limited,native);},"Network native work limit terminates execution.");auto cancelled=native;cancelled.cancellation=std::make_shared<std::atomic_bool>(true);rejects([&]{solver.solve(growth,one,1,{1},{},options,cancelled);},"Cancellation reaches native network callback/integration.");edge.weights={-1};options.diffusion={.7};rejects([&]{solver.solve(stationary,edge,1,{1,3},{},options,native);},"Negative diffusion weights are not silently accepted as ordinary diffusion.");options.generalCoupling=true;const auto signedResult=solver.solve(stationary,edge,1,{1,3},{},options,native);expect(signedResult.values.back()>3,"Explicit general coupling permits signed real operators.");
}
#ifndef PENTA_NETWORK_DRIVER_ONLY
void language(const std::filesystem::path& temp){penta::runtime::ExecutionOptions options;options.dataDirectory=temp;options.odeCacheDirectory=temp/"language-odes";auto result=penta::runtime::execute("ode local_node(t,pentarnion p){p'=0*p;}record G=graph([1,2]);matrix P=[1+i;3+j];record s=networksolve(local_node,G,P,options(t1=1,step=0.01,sample_step=0.1,diffusion=0.7,threads=2));matrix node_i=networkcoeff(s,1,2);assert(s.nodes==2);assert(s.coordinates==5);assert(s.state_widths(1)==5);assert(abs(node_i(end)-0.5-0.5*exp(-1.4))<1e-9);assert(s.method==\"rk4\");plot(s.t,node_i);",{},options);expect(result.ok(),"Network DSL returns typed all-coefficient records and plottable node columns.");if(!result.ok()){for(const auto& d:result.analysis.diagnostics)std::cerr<<d.code<<": "<<d.message<<'\n';for(const auto& d:result.runtimeDiagnostics)std::cerr<<d.code<<": "<<d.message<<'\n';}}
#endif
}
int main(){const auto temp=std::filesystem::temp_directory_path()/("penta-network-test-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));try{std::filesystem::create_directories(temp);driver(temp);
#ifndef PENTA_NETWORK_DRIVER_ONLY
language(temp);
#endif
}catch(const std::exception& error){++failures;std::cerr<<error.what()<<'\n';}std::cout<<checks<<" native network checks, "<<failures<<" failures\n";return failures?1:0;}
